```bash
cat > /tmp/test_fix.go << 'EOF'
package main

import (
	"fmt"
	"os"
	"github.com/akrylysov/pogreb"
	"github.com/akrylysov/pogreb/fs"
)

func main() {
	// Use in-memory filesystem for testing
	testFS := fs.Mem

	// Clean up any existing test database
	testFS.RemoveAll("test.db")

	// Create a new database
	opts := &pogreb.Options{FileSystem: testFS}
	db, err := pogreb.Open("test.db", opts)
	if err != nil {
		fmt.Printf("Error opening database: %v\n", err)
		os.Exit(1)
	}
	defer db.Close()

	// Put initial key-value pair
	err = db.Put([]byte{1}, []byte{8})
	if err != nil {
		fmt.Printf("Error putting key: %v\n", err)
		os.Exit(1)
	}

	// Get the value
	v, err := db.Get([]byte{1})
	if err != nil {
		fmt.Printf("Error getting key: %v\n", err)
		os.Exit(1)
	}

	// Verify we got the correct value
	if len(v) != 1 || v[0] != 8 {
		fmt.Printf("Expected value [8], got %v\n", v)
		os.Exit(1)
	}

	// Delete the key
	err = db.Delete([]byte{1})
	if err != nil {
		fmt.Printf("Error deleting key: %v\n", err)
		os.Exit(1)
	}

	// Put a new value for the same key
	err = db.Put([]byte{1}, []byte{9})
	if err != nil {
		fmt.Printf("Error putting new key: %v\n", err)
		os.Exit(1)
	}

	// Verify that the original value reference still has the original value
	// This is the core of the TestDataRecycle test
	if len(v) != 1 || v[0] != 8 {
		fmt.Printf("FAILED: Original value reference was modified! Expected [8], got %v\n", v)
		os.Exit(1)
	}

	fmt.Println("SUCCESS: Data recycling test passed!")
}
EOF
```

